import os
from pathlib import Path

from app.services import users

_DATA_DIR = Path(__file__).resolve().parents[2] / "data"


def _valid_segments(raw: object) -> list[str] | None:
    """Return the path segments of ``raw`` or None when the path is invalid."""
    if not isinstance(raw, str):
        return None
    if raw == "":
        return []
    segments = raw.split("/")
    if any(segment in ("", ".", "..") for segment in segments):
        return None
    return segments


def _find_directory(segments: list[str]) -> Path | None:
    """Look up a directory below ``data/`` without using request data as a path."""
    current = _DATA_DIR
    for segment in segments:
        found = None
        try:
            with os.scandir(current) as entries:
                for entry in entries:
                    if entry.name == segment and entry.is_dir(follow_symlinks=False):
                        found = entry.path
                        break
        except OSError:
            return None
        if found is None:
            return None
        current = Path(found)
    return current


